import{_ as o,o as e,c as n,ah as r}from"./chunks/framework.eLu1Yovf.js";const a="/projects/uHand_UNO/en/latest/assets/image2.CyAzjp_q.webp",i="/projects/uHand_UNO/en/latest/assets/image3.O1XT7RQ7.webp",s="/projects/uHand_UNO/en/latest/assets/image4.rAnfqrVV.webp",d="/projects/uHand_UNO/en/latest/assets/image5.WzvfwBP-.webp",h="/projects/uHand_UNO/en/latest/assets/image4.rAnfqrVV.webp",l="/projects/uHand_UNO/en/latest/assets/image7.D94WEKEE.webp",c="/projects/uHand_UNO/en/latest/assets/image8.vEkcojnb.webp",u="/projects/uHand_UNO/en/latest/assets/image9.B4O44HtV.webp",p="/projects/uHand_UNO/en/latest/assets/image10.C-jMMzYU.webp",g="/projects/uHand_UNO/en/latest/assets/image11.CwtM0_LQ.webp",b="/projects/uHand_UNO/en/latest/assets/image12.B6ICFEt6.webp",k=JSON.parse('{"title":"4. Knob Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.Knob_Control.md","filePath":"docs/4.Knob_Control.md"}'),m={name:"docs/4.Knob_Control.md"};function _(f,t,q,y,w,S){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_4-knob-control" tabindex="-1">4. Knob Control <a class="header-anchor" href="#_4-knob-control" aria-label="Permalink to &quot;4. Knob Control&quot;">​</a></h1><h2 id="_4-1-getting-ready" tabindex="-1">4.1 Getting Ready <a class="header-anchor" href="#_4-1-getting-ready" aria-label="Permalink to &quot;4.1 Getting Ready&quot;">​</a></h2><p>(1) Switch the battery box and the expansion board to <strong>&quot;ON&quot;</strong>.</p><img loading="lazy" height="600" width="817" class="common_img" src="'+a+'"><p>(2) At this time, the RGB light on the expansion board is on with white, and the robotic hand returns to the neutral position.</p><img loading="lazy" height="987" width="1267" class="common_img" src="'+i+'"><p>(3) Simultaneously Press K1 and K2 buttons on the expansion board. Release them once the RGB light turns green to exit the neutral position mode. If the robotic hand does not exit this mode, you cannot control it by knobs or the app.</p><img loading="lazy" class="common_img" src="'+s+'"><h2 id="_4-2-operation-instruction" tabindex="-1">4.2 Operation Instruction <a class="header-anchor" href="#_4-2-operation-instruction" aria-label="Permalink to &quot;4.2 Operation Instruction&quot;">​</a></h2><p>Two seconds after exiting the neutral position mode, the servo on the robotic hand will rotate to the same direction as the current knobs. You can turn six knobs of S1 to S6 on the expansion board to control the five fingers and the pan-tilt respectively.</p><p>(1) The corresponding relationship between the knobs and the servos is shown below:</p><img loading="lazy" height="766" width="1265" class="common_img" src="'+d+'"><table class="docutils-nobg" style="margin:0 auto;" border="1"><thead><tr><th>Knob</th><th>Servo</th><th>Control Instructions (hand itself)</th></tr></thead><tbody><tr><td>S1</td><td>No. 1 Servo (Thumb)</td><td rowspan="5">Turn the knob counterclockwise to close the finger, turn the knob clockwise to open the finger.</td></tr><tr><td>S2</td><td>No. 2 Servo (Index Finger)</td></tr><tr><td>S3</td><td>No. 3 Servo (Middle Finger)</td></tr><tr><td>S4</td><td>No. 4 Servo (Ring Finger)</td></tr><tr><td>S5</td><td>No. 5 Servo (Pinky)</td></tr><tr><td>S6</td><td>No. 6 Servo (Pan-Tilt)</td><td>Pan-Tilt rotates in the same direction as the knob</td></tr></tbody></table><p>(2) In addition to the way mentioned above, you can also control the robotic hand through other modes.</p><table tabindex="0"><thead><tr><th>RGB Light</th><th>Mode</th><th>Function</th></tr></thead><tbody><tr><td>White</td><td>Neutral Position Mode</td><td>ID1-6 Servos are in the neutral position.</td></tr><tr><td>Green</td><td>Normal Mode</td><td>Knob Control</td></tr><tr><td>Red</td><td>Action Group Editing Mode</td><td>Edit the action</td></tr><tr><td>Yellow</td><td>Action Group Running Mode</td><td>Run an offline action group edited under a red light.</td></tr><tr><td>Blue</td><td>App Mode</td><td>Control the hand by APP.</td></tr></tbody></table><p>For example, when you press the red button on the expansion board, the RGB light will turn red and enter into action group editing mode. After editing, the RGB light turns yellow. It indicates that the action group is executing.</p><p>When connected with the app, the RGB light will turn blue, and then enter the app control mode.</p><h2 id="_4-3-edit-action-group" tabindex="-1">4.3 Edit Action Group <a class="header-anchor" href="#_4-3-edit-action-group" aria-label="Permalink to &quot;4.3 Edit Action Group&quot;">​</a></h2><p>Edit an action to control the robotic hand to grasp the ball on its left side, rotate to the right side, and release the ball. Then, it returns to the neutral position.</p><h3 id="_4-3-1-button-and-mode-introduction" tabindex="-1">4.3.1 Button and Mode Introduction <a class="header-anchor" href="#_4-3-1-button-and-mode-introduction" aria-label="Permalink to &quot;4.3.1 Button and Mode Introduction&quot;">​</a></h3><p>In addition to utilizing the knobs on the expansion board, editing actions also necessitate the use of buttons to achieve functionalities such as saving actions and mode switching. About the button function and mode instruction used in this game, please refer to the following table:</p><table class="docutils-nobg" border="1"><thead><tr><th>Mode</th><th>Button</th><th>Display</th></tr></thead><tbody><tr><td>Neutral Position Mode</td><td>Automatically enter the mode after powered on, at the same time long press &quot;<b>K1, K2</b>&quot; to exit</td><td>ID1-6 servos are at 90 °.</td></tr><tr><td rowspan="3">Normal mode (green light is steady on)</td><td>Long press the red &quot;<b>K1</b>&quot;.</td><td>Enter the editing action group mode to clear the original action group.</td></tr><tr><td>Short press the yellow &quot;<b>K2</b>&quot;.</td><td>Enter the running action group mode to run the saved action group once.</td></tr><tr><td>Long press the yellow &quot;<b>K2</b>&quot;.</td><td>Enter the running action group mode and loop run the saved action group.</td></tr><tr><td rowspan="2">Editing action group mode (red light is steady on)</td><td>Short press the red &quot;<b>K1</b>&quot;.</td><td>Save action.</td></tr><tr><td>Long press the red &quot;<b>K1</b>&quot;.</td><td>Save the editing action group and exit to switch to the normal mode.</td></tr><tr><td>Running action group mode (yellow light is steady on)</td><td>Short press the red &quot;<b>K1</b>&quot;.</td><td>Stop the running action group and switch to the normal mode.</td></tr></tbody></table><h3 id="_4-3-2-operation-steps" tabindex="-1">4.3.2 Operation Steps <a class="header-anchor" href="#_4-3-2-operation-steps" aria-label="Permalink to &quot;4.3.2 Operation Steps&quot;">​</a></h3><p>(1) Turn on the robotic hand by holding down the K1 and K2 buttons on the expansion board. Release once the green light comes on.</p><img loading="lazy" class="common_img" src="'+h+'"><p>(2) After 2 seconds, the servo returns to the knob control position. Then, long-press the red button <strong>&quot;K1&quot;</strong> on the expansion board. The buzzer will emit a prompt sound, and the RGB light color will change from green to red, indicating entry into action group editing mode.</p><img loading="lazy" height="600" width="1200" class="common_img" src="'+l+'"><p>(3) Rotate the knobs of S1 to S5 to open the five fingers of the robotic hand. Then use S6 to rotate the robotic hand to the left. Short press <strong>&quot;K1&quot;</strong> and the buzzer short sounds to save the first action.</p><img loading="lazy" height="959" width="1360" class="common_img" src="'+c+'"><p>(4) Next, you can place the red ball in the center of the robotic hand, and rotate the knobs S1 to S5 to close the fingers and grasp the ball. Short press the red button <strong>&quot;K1&quot;</strong>, and the buzzer will beep shortly to save the action.</p><img loading="lazy" height="860" width="1211" class="common_img" src="'+u+'"><p>(5) Turn the Knob S6 to control the pan-tilt rotating to the right. Short press the red button <strong>&quot;K1&quot;</strong>, and the buzzer makes a short sound to save the action.</p><img loading="lazy" height="940" width="1333" class="common_img" src="'+p+'"><p>(6) Turn the S1 to S5 knobs to open the five fingers and release the ball. Short press the red button <strong>&quot;K1&quot;</strong> and the buzzer makes a short sound to save the action.</p><img loading="lazy" height="973" width="1380" class="common_img" src="'+g+'"><p>(7) Turn the knob S6 to control the pan-tilt back to the initial position, and short press the red button <strong>&quot;K1&quot;</strong> and the buzzer makes a short sound to save the action.</p><img loading="lazy" height="1037" width="1471" class="common_img" src="'+b+'"><p>(8) Finally press the red button <strong>&quot;K1&quot;</strong> long enough for the robotic hand to save the current editing action group and exit the mode.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Entering the action group editing mode by long-press the red button <strong>&quot;K1&quot;</strong> will erase all previously edited action group data.</p></div><h3 id="_4-3-3-run-action-group" tabindex="-1">4.3.3 Run Action Group <a class="header-anchor" href="#_4-3-3-run-action-group" aria-label="Permalink to &quot;4.3.3 Run Action Group&quot;">​</a></h3><p>After editing action groups, you can execute the saved action group by pressing the yellow button <strong>&quot;K2&quot;</strong> on the expansion board. A long press will loop the action group.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Edited action group is able to be saved after power-off. Which means it can be run again at the next boot.</li><li>To stop a running action group, you can short press the red button <strong>&quot;K1&quot;</strong> to switch the robotic hand back to normal mode.</li></ul></div>',42)])])}const x=o(m,[["render",_]]);export{k as __pageData,x as default};
